/* Offline artwork data-URI bundle. SVG assets are embedded from checked-in source files.
 * Browser consumer: add data-embedded-wallpaper="<key>" to an img/background container.
 * Native desktop/GRUB consumers must explicitly load their packaged asset; this JS alone does not wire them.
 */
(function (root) {
  "use strict";
  var artwork = Object.freeze({
    "chimeraAurora": "data:image/svg+xml;base64,",
    "octavianAurora": "data:image/svg+xml;base64,",
    "marine": "data:image/svg+xml;base64,",
    "auroraGlassJpeg": "data:image/jpeg;base64,",
    "octavianBootSplash": "data:image/svg+xml;base64,",
    "octavianMobile": "data:image/svg+xml;base64,",
    "octavianAuroraBootSplash": "data:image/svg+xml;base64,",
    "octavianAuroraDesktop": "data:image/svg+xml;base64,",
    "octavianInstaller": "data:image/svg+xml;base64,",
    "octavianLibrary": "data:image/svg+xml;base64,",
    "octavianWaylandGlassSvg": "data:image/svg+xml;base64,",
    "octavianJasperBoot": "data:image/svg+xml;base64,",
    "octavianSpitfireBoot": "data:image/svg+xml;base64,"
  });
  root.OS_EMBEDDED_ARTWORK = artwork;
  function applyArtwork(scope) {
    if (typeof document === "undefined") return;
    var nodes = (scope || document).querySelectorAll("[data-embedded-wallpaper]");
    nodes.forEach(function (node) {
      var uri = artwork[node.getAttribute("data-embedded-wallpaper")];
      if (!uri) return;
      if (node.tagName && node.tagName.toLowerCase() === "img") node.src = uri;
      else { node.style.backgroundImage = 'url("' + uri + '")'; node.style.backgroundSize = node.style.backgroundSize || "cover"; node.style.backgroundPosition = node.style.backgroundPosition || "center"; }
    });
  }
  root.applyOSEmbeddedArtwork = applyArtwork;
  if (typeof document !== "undefined") { if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", function () { applyArtwork(document); }, { once: true }); else applyArtwork(document); }
})(typeof window !== "undefined" ? window : this);
